package com.smartroute;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.stereotype.Service;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import com.github.benmanes.caffeine.cache.*;
import java.time.*;
import java.util.*;
import static com.smartroute.TomTomService.*;

@Service
public class RealJourneyPlanner {
 public record Request(@NotNull @Valid LiveRequest journey,@NotBlank @Pattern(regexp="TOMTOM|JAVA") String engine,
  @NotBlank @Pattern(regexp="DIJKSTRA|TIME_DEPENDENT|ALT") String algorithm,@NotBlank @Pattern(regexp="NORMAL|MORNING|EVENING") String scenario,
  @Min(0) @Max(1440) int stopMinutes,@DecimalMin("0") @DecimalMax("2000") Double fuelRange,@DecimalMin("0") @DecimalMax("500") double reserve,
  @Pattern(regexp="PETROL|RESTAURANT|HOTEL") String category,String selectedPoiId,boolean emergency,boolean preferBusierRoads) {}
 public record Candidate(SearchPlace place,boolean feasible,Double firstLegKm,Double totalKm,Double totalMinutes,Double detourKm,String message) {}
 public record Result(String provider,String fetchedAt,List<ProviderRoute> routes,String notice,String algorithm,RealRoadService.Metrics metrics,List<Double> snapDistancesMeters,
   List<RealRoadService.RoadCoverage> roadCoverage,boolean busierPreferenceApplied,SearchPlace chosenStop,List<Candidate> candidates,double stopSeconds,Double firstLegKm,Double detourKm) {}
 record Calculation(String provider,List<ProviderRoute> routes,String notice,RealRoadService.Metrics metrics,List<Double> snaps,List<RealRoadService.RoadCoverage> coverage,boolean busierApplied) {}
 record Evaluation(Candidate candidate,Calculation calculation) {}
 private final TomTomService tomtom;private final RealRoadService osm;
 private final Cache<Request,Result> cache=Caffeine.newBuilder().maximumSize(150).expireAfterWrite(Duration.ofSeconds(60)).build();
 public RealJourneyPlanner(TomTomService tomtom,RealRoadService osm){this.tomtom=tomtom;this.osm=osm;}
 public List<Result> evaluate(Request r){validate(r);if(!r.engine.equals("JAVA"))throw new IllegalArgumentException("Algorithm comparison is available for Java OSM routing.");return (r.emergency?List.of("TIME_DEPENDENT"):r.preferBusierRoads?List.of("DIJKSTRA","ALT"):List.of("DIJKSTRA","TIME_DEPENDENT","ALT")).stream().map(a->compute(new Request(r.journey,r.engine,a,r.scenario,r.stopMinutes,r.fuelRange,r.reserve,r.category,r.selectedPoiId,r.emergency,r.preferBusierRoads))).toList();}
 public Result plan(Request request){validate(request);return cache.get(request,this::compute);}
 private void validate(Request r){tomtom.journey(r.journey);if(r.engine.equals("JAVA")&&r.preferBusierRoads&&!r.emergency&&r.algorithm.equals("TIME_DEPENDENT"))throw new IllegalArgumentException("Choose static Dijkstra or ALT for the main-road preference. Time-dependent Dijkstra uses travel-time costs only.");if(r.fuelRange!=null&&r.category!=null&&!r.category.equals("PETROL"))throw new IllegalArgumentException("Fuel planning requires a petrol-pump stop.");if((r.category!=null||r.fuelRange!=null)&&!r.journey.stops().isEmpty())throw new IllegalArgumentException("Use either manual stops or one recommended category stop in this journey.");if(r.selectedPoiId!=null&&r.category==null&&r.fuelRange==null)throw new IllegalArgumentException("Choose a stop category before selecting a nearby place.");if(r.journey.departure()!=null){try{LocalDateTime departure=LocalDateTime.parse(r.journey.departure());if(departure.isBefore(LocalDateTime.now(ZoneId.of("Asia/Kolkata")).minusMinutes(2)))throw new IllegalArgumentException("Choose now or a future departure time.");if(departure.isAfter(LocalDateTime.now(ZoneId.of("Asia/Kolkata")).plusDays(30)))throw new IllegalArgumentException("Choose a departure within the next 30 days.");}catch(java.time.format.DateTimeParseException e){throw new IllegalArgumentException("Provide a local departure date/time such as 2026-11-17T09:00.");}}}
 LiveRequest journey(Request r,List<Location> stops,String departure){return new LiveRequest(r.journey.source(),r.journey.destination(),r.emergency?"FASTEST":r.journey.objective(),r.journey.origin(),r.journey.destinationPoint(),stops,r.journey.avoidTolls(),r.journey.avoidHighways(),departure);}
 public List<SearchPlace> nearby(Request r){validate(r);String category=r.fuelRange!=null?"PETROL":r.category;if(category==null)throw new IllegalArgumentException("Choose a stop category.");List<Location> points=tomtom.journey(r.journey);Location origin=points.getFirst(),end=points.getLast();double usable=r.fuelRange==null?20:Math.max(0,r.fuelRange-r.reserve);if(r.fuelRange!=null&&usable<=0)return List.of();Location center=r.fuelRange!=null?origin:new Location("Journey midpoint",(origin.lat()+end.lat())/2,(origin.lng()+end.lng())/2);int radius=r.fuelRange!=null?(int)Math.min(20000,Math.max(200,usable*1000)):(int)Math.min(20000,Math.max(3000,RealRoadService.distance(origin.lat(),origin.lng(),end.lat(),end.lng())*500+3000));return tomtom.nearby(center,category,radius);}
 private Result compute(Request r){
  if(r.fuelRange!=null&&r.fuelRange-r.reserve<=0)return empty(r,"No feasible petrol pump: the remaining range does not exceed the safety reserve.",List.of());
  LiveRequest direct=journey(r,List.of(),r.journey.departure());Calculation baseline=calculate(r,direct);
  if(r.category==null&&r.fuelRange==null){Calculation chosen=r.journey.stops().isEmpty()?baseline:withDwell(r,journey(r,r.journey.stops(),r.journey.departure()));return response(r,chosen,null,List.of(),r.journey.stops().size()*r.stopMinutes*60.0,null,null);}

  List<SearchPlace> nearby=nearby(r);List<SearchPlace> candidates=r.selectedPoiId==null?nearby.stream().limit(3).toList():nearby.stream().filter(p->p.id().equals(r.selectedPoiId)).toList();
  if(r.selectedPoiId!=null&&candidates.isEmpty())throw new IllegalArgumentException("The selected place is no longer in the nearby results. Search nearby again.");
  List<Evaluation> evaluated=new ArrayList<>();List<Candidate> all=new ArrayList<>();List<Location> ends=tomtom.journey(direct);
  for(SearchPlace place:candidates){Location stop=new Location(place.label(),place.lat(),place.lng());try{
   LiveRequest first=new LiveRequest(null,null,direct.objective(),ends.getFirst(),stop,List.of(),direct.avoidTolls(),direct.avoidHighways(),direct.departure());Calculation firstLeg=calculate(r,first);ProviderRoute a=firstLeg.routes.getFirst();
   if(r.fuelRange!=null&&a.distanceKm()>r.fuelRange-r.reserve+1e-8){all.add(new Candidate(place,false,a.distanceKm(),null,null,null,"Beyond the usable driving range after reserve."));continue;}
   String next=nextDeparture(a,r.stopMinutes);LiveRequest second=new LiveRequest(null,null,direct.objective(),stop,ends.getLast(),List.of(),direct.avoidTolls(),direct.avoidHighways(),next);Calculation combined=combine(List.of(firstLeg,calculate(r,second)),r.stopMinutes*60.0);
   ProviderRoute route=combined.routes.getFirst();double detour=route.distanceKm()-baseline.routes.getFirst().distanceKm();Candidate candidate=new Candidate(place,true,a.distanceKm(),route.distanceKm(),(route.travelSeconds()+r.stopMinutes*60)/60,detour,"Road routes evaluated for both legs. Opening hours and fuel availability are not verified.");all.add(candidate);evaluated.add(new Evaluation(candidate,combined));
  }catch(IllegalArgumentException e){all.add(new Candidate(place,false,null,null,null,null,"No supported road journey could be calculated to this place."));}catch(ResponseStatusException e){throw e;}}
  if(evaluated.isEmpty())return empty(r,"No feasible stop among the evaluated nearby results"+(r.fuelRange!=null?" within your usable driving range.":" for these journey settings."),all);
  evaluated.sort(Comparator.comparingDouble(e->score(r,e.calculation)));Evaluation best=evaluated.getFirst();return response(r,best.calculation,best.candidate.place,all,r.stopMinutes*60.0,best.candidate.firstLegKm,best.candidate.detourKm);
 }
 private double score(Request r,Calculation c){ProviderRoute route=c.routes.getFirst();double score=r.emergency||r.journey.objective().equals("FASTEST")?route.travelSeconds():route.distanceKm();if(r.preferBusierRoads&&!r.emergency&&c.busierApplied)score*=1+1.5*(1-c.coverage.getFirst().mainRoadShare());return score;}
 private Result empty(Request r,String message,List<Candidate> candidates){return new Result(r.engine.equals("JAVA")?"Java + OpenStreetMap":"TomTom",Instant.now().toString(),List.of(),message,r.algorithm,null,List.of(),List.of(),false,null,candidates,0,null,null);}
 private Result response(Request r,Calculation c,SearchPlace stop,List<Candidate> candidates,double dwell,Double firstLeg,Double detour){String notice=c.notice.replace("without dwell time", "with configured dwell time when enabled")+" "+(r.emergency?"Academic emergency demonstration: minimum travel time; busier-road preference is disabled. Not emergency navigation. ":"")+(candidates.isEmpty()?"":"Recommendation compares up to three returned nearby places over the complete journey. Not a city-wide optimum. ")+(r.fuelRange!=null?"Fuel reachability checks the routed first leg minus the reserve. A refill is assumed sufficient for the onward leg. ":"")+(dwell>0?"Arrival includes "+Math.round(dwell/60)+" minutes of stop time. ":"")+(r.preferBusierRoads&&!r.emergency?"Main-road classification is only a busier-road proxy, not measured vehicle counts or a safety guarantee.":"");return new Result(c.provider,Instant.now().toString(),c.routes,notice,r.emergency&&r.engine.equals("JAVA")?"TIME_DEPENDENT":r.algorithm,c.metrics,c.snaps,c.coverage,c.busierApplied,stop,candidates,dwell,firstLeg,detour);}
 private Calculation calculate(Request r,LiveRequest journey){
  boolean prefer=r.preferBusierRoads&&!r.emergency;Calculation raw;
  if(r.engine.equals("JAVA")){RealRoadService.Result result=osm.route(new RealRoadService.Request(journey,r.emergency?"TIME_DEPENDENT":r.algorithm,r.scenario,prefer));raw=new Calculation(result.provider(),result.routes(),result.notice(),result.metrics(),result.snapDistancesMeters(),List.of(),prefer);if(prefer){var fastest=osm.route(new RealRoadService.Request(journey,r.algorithm,r.scenario,false));if(result.routes().getFirst().travelSeconds()>fastest.routes().getFirst().travelSeconds()*1.3)raw=new Calculation(fastest.provider(),fastest.routes(),fastest.notice()+" Main-road preference would exceed the 30% travel-time allowance, so the baseline route is shown.",fastest.metrics(),fastest.snapDistancesMeters(),List.of(),false);}}
  else{LiveResult result=tomtom.route(journey);raw=new Calculation(result.provider(),result.routes(),result.notice(),null,List.of(),List.of(),false);}
  List<ProviderRoute> routes=new ArrayList<>(raw.routes);List<RealRoadService.RoadCoverage> coverage=routes.stream().map(osm::coverage).toList();boolean applied=raw.busierApplied;
  if(prefer&&r.engine.equals("TOMTOM")){double minTime=routes.stream().mapToDouble(ProviderRoute::travelSeconds).min().orElseThrow();int best=0;double share=-1;for(int i=0;i<routes.size();i++){var cov=coverage.get(i);if(cov.coverage()>=.7&&routes.get(i).travelSeconds()<=minTime*1.3&&cov.mainRoadShare()>share){share=cov.mainRoadShare();best=i;}}if(share>=0){Collections.swap(routes,0,best);applied=true;}else applied=false;coverage=routes.stream().map(osm::coverage).toList();}
  String note=raw.notice;if(prefer)note+=" "+(applied?"Main-road preference applied using OSM classification, with a maximum 30% travel-time allowance. Provider mode ranks only the returned alternatives. ":"Main-road preference could not be applied with sufficient local map coverage or within the travel-time allowance. ");return new Calculation(raw.provider,List.copyOf(routes),note,raw.metrics,raw.snaps,coverage,applied);
 }
 private Calculation withDwell(Request r,LiveRequest journey){if(r.stopMinutes==0)return calculate(r,journey);List<Location> points=tomtom.journey(journey);List<Calculation> legs=new ArrayList<>();String departure=journey.departure();for(int i=1;i<points.size();i++){var leg=new LiveRequest(null,null,journey.objective(),points.get(i-1),points.get(i),List.of(),journey.avoidTolls(),journey.avoidHighways(),departure);Calculation result=calculate(r,leg);legs.add(result);departure=nextDeparture(result.routes.getFirst(),r.stopMinutes);}return combine(legs,(points.size()-2)*r.stopMinutes*60.0);}
 private String nextDeparture(ProviderRoute route,int stopMinutes){return OffsetDateTime.parse(route.arrival()).atZoneSameInstant(ZoneId.of("Asia/Kolkata")).toLocalDateTime().plusMinutes(stopMinutes).toString();}
 private Calculation combine(List<Calculation> legs,double dwell){List<Point> points=new ArrayList<>();List<Section>sections=new ArrayList<>();List<Instruction>instructions=new ArrayList<>();List<Double>snaps=new ArrayList<>();double km=0,travel=0,delay=0,free=0,historical=0,offset=0,exec=0,prep=0;int visited=0,settled=0;boolean hasFree=true,hasHistory=true,applied=true;for(int i=0;i<legs.size();i++){Calculation c=legs.get(i);ProviderRoute route=c.routes.getFirst();int pointOffset=points.size();points.addAll(route.points());for(Section section:route.sections())sections.add(new Section(section.start()+pointOffset,section.end()+pointOffset,section.category(),section.magnitude(),section.delaySeconds()));for(Instruction instruction:route.instructions())instructions.add(new Instruction(instruction.offsetMeters()+offset,instruction.travelSeconds()+travel+(i==0?0:dwell*i/Math.max(1,legs.size()-1)),instruction.message(),instruction.street(),instruction.maneuver(),instruction.point()));offset+=route.distanceKm()*1000;km+=route.distanceKm();travel+=route.travelSeconds();delay+=route.delaySeconds();if(route.freeFlowSeconds()==null)hasFree=false;else free+=route.freeFlowSeconds();if(route.historicalSeconds()==null)hasHistory=false;else historical+=route.historicalSeconds();snaps.addAll(c.snaps);applied&=c.busierApplied;if(c.metrics!=null){exec+=c.metrics.executionMs();prep+=c.metrics.preprocessingMs();visited+=c.metrics.visitedNodes();settled+=c.metrics.settledNodes();}}
  ProviderRoute joined=new ProviderRoute(km,travel,delay,legs.getLast().routes.getFirst().arrival(),points,sections,hasFree?free:null,hasHistory?historical:null,instructions,legs.size());var metrics=legs.getFirst().metrics==null?null:new RealRoadService.Metrics(exec,prep,visited,settled);return new Calculation(legs.getFirst().provider,List.of(joined),legs.getFirst().notice,metrics,snaps,List.of(osm.coverage(joined)),applied);
 }
}
@RestController @RequestMapping("/api/journeys")
class RealJourneyApi {
 private final RealJourneyPlanner planner;RealJourneyApi(RealJourneyPlanner planner){this.planner=planner;}
 @PostMapping("/evaluate") List<RealJourneyPlanner.Result> evaluate(@Valid @RequestBody RealJourneyPlanner.Request request){return planner.evaluate(request);}
 @PostMapping("/plan") RealJourneyPlanner.Result plan(@Valid @RequestBody RealJourneyPlanner.Request request){return planner.plan(request);}
 @PostMapping("/nearby") List<SearchPlace> nearby(@Valid @RequestBody RealJourneyPlanner.Request request){return planner.nearby(request);}
}
